class Solution {
  public int maxBalancedShipments(int[] weight) {
    int shipments = 0, max = 0;
    for (int w : weight) {
      if (w < max) {
        shipments++; // close a shipment as early as possible
        max = 0;
      } else {
        max = w;
      }
    }
    return shipments;
  }
}
